package se.anders.tunerstudio.pidautotune.session;
/** Read-only comparison between two archived DC-IAC tuning sessions. */
public final class DcIacIterationComparison {public static final String INSUFFICIENT="INSUFFICIENT",NOT_COMPARABLE="NOT_COMPARABLE",IMPROVED="IMPROVED",MIXED="MIXED",REGRESSED="REGRESSED",SIMILAR="SIMILAR";private final String status,detail;private final int baselineSequence,candidateSequence,improvedMetrics,regressedMetrics;public DcIacIterationComparison(String status,int baselineSequence,int candidateSequence,int improvedMetrics,int regressedMetrics,String detail){this.status=status==null?"":status;this.baselineSequence=baselineSequence;this.candidateSequence=candidateSequence;this.improvedMetrics=improvedMetrics;this.regressedMetrics=regressedMetrics;this.detail=detail==null?"":detail;}public String getStatus(){return status;}public int getBaselineSequence(){return baselineSequence;}public int getCandidateSequence(){return candidateSequence;}public int getImprovedMetrics(){return improvedMetrics;}public int getRegressedMetrics(){return regressedMetrics;}public String getDetail(){return detail;}}
